sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float amount;
uniform float radius;
uniform float feather;
layout(color) uniform half4 vigColor;
uniform float curve;
uniform float invertPulse;
uniform float2 center;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float3 s = unp(c);
    float2 p = (coord / size - center) * float2(size.x / size.y, 1.0) * 2.0;
    float pulse = invertPulse > 0.5 ? 1.0 - e : e;
    float v = smoothstep(radius + (1.0 - pulse) * 0.3, radius + (1.0 - pulse) * 0.3 + feather, length(p));
    float3 o = mix(s, float3(vigColor.rgb), v * amount * (0.4 + 0.6 * pulse));
    return fin(c, float4(o * c.a, c.a), opacity);
}
